+	if n < 0 {
 		return 0
 	}
-	return value
+	return n
 }

func nonNegative(value int) int {
	if value < 0 {
		return 0
	}
	return value
}

		if cost, ok := models.EstimateCost(model, usage.InputTokens, usage.CachedInputTokens, usage.CacheWriteTokens, usage.OutputTokens); ok {
			if prepared.Summary.CostUSD == nil {
				prepared.Summary.CostUSD = &cost
			} else {
				total := *prepared.Summary.CostUSD + cost
				prepared.Summary.CostUSD = &total
			}
		} else {
			prepared.Summary.CostUSD = nil
		}
		prepared.Applied = true
	}
	return prepared
}

	retrieval.Grounding = unknownGrounding("below_threshold", 0)
	completion.Output = UnknownRAGAnswer
	if dialogueMode {
		completion.Output += "\n\nИсточники: подтверждающие источники не найдены."
	}
} else if strictRAG {
	completion, invariantCheck, err = a.completeGrounded(ctx, completionRequest, retrieval, guard)
} else if !retrieval.Empty {
	completion, invariantCheck, err = a.completeWithInvariants(ctx, completionRequest, guard)
}
if err != nil {
	response.Duration = time.Since(started)
	return response, err
}

if completion.Model == "" {
	completion.Model = request.Model
}
if completion.Usage.TotalTokens == 0 {
	completion.Usage.TotalTokens = completion.Usage.InputTokens + completion.Usage.OutputTokens
}

response.Text = completion.Output
response.Retrieval.RecordCitations(response.Text)
response.Model = completion.Model
response.Usage = sumUsage(completion.Usage, retrieval.AuxiliaryUsage())
response.Duration = time.Since(started)
if cost, ok := models.EstimateCost(request.Model, completion.Usage.InputTokens, completion.Usage.CachedInputTokens, completion.Usage.CacheWriteTokens, completion.Usage.OutputTokens); ok {
	response.CostUSD = &cost
}
for _, step := range retrieval.Steps {
	if cost, ok := models.EstimateCost(step.Model, step.Usage.InputTokens, step.Usage.CachedInputTokens, step.Usage.CacheWriteTokens, step.Usage.OutputTokens); ok {
		response.CostUSD = addKnownCosts(response.CostUSD, &cost)
	} else {
		response.CostUSD = nil
		break
	}
}
